159	// CreateSession 为账户创建一个绑定设备、带到期时间的会话。
160	//
161	// 会话编号全局唯一；账户必须存在。
162	func (w *Wallet) CreateSession(id, accountID, deviceID string, expiresAt time.Time) (SessionView, error) {
163		if id == "" || accountID == "" || deviceID == "" {
164			return SessionView{}, fmt.Errorf("%w: session id, account id and device id are required", ErrInvalidArgument)
165		}
166	
167		w.mu.Lock()
168		defer w.mu.Unlock()
169	
170		if _, ok := w.accounts[accountID]; !ok {
171			return SessionView{}, fmt.Errorf("%w: %s", ErrAccountNotFound, accountID)
172		}
173		if _, ok := w.sessions[id]; ok {
174			return SessionView{}, fmt.Errorf("%w: %s", ErrSessionExists, id)
175		}
176		now := w.now()
177		sess := &session{
178			id:        id,
179			accountID: accountID,
180			deviceID:  deviceID,
181			expiresAt: expiresAt,
182			createdAt: now,
183		}
184		w.sessions[id] = sess
185		return sess.view(), nil
186	}
