337	// DeactivatePolicy 由出资账户主动停用一条代付策略，立即停止该策略继续
338	// 受理代付。停用不可撤销。
339	//
340	// 必须使用该策略出资账户绑定当前设备的有效会话：会话不存在、不属于出资
341	// 账户、设备不符、已吊销或已到期时返回 ErrNotPolicyOwner，不改变策略、
342	// 请求或账本。策略编号、会话编号、设备缺失，或理由去掉首尾空白后为空，
343	// 返回 ErrInvalidArgument。策略不存在返回 ErrPolicyNotFound。保存与比较
344	// 理由均使用去掉首尾空白后的内容。
345	//
346	// 再次停用仍须通过会话校验：理由与首次相同时幂等返回首次结果，理由不同
347	// 返回 ErrConflict；两者都不改写首次停用信息，也不增加账本记录。尚未
348	// 开始或已经结束的策略也允许停用；停用后该编号不能再保存成新策略。
349	//
350	// 停用成功时，该策略下未到等待期限的待审批请求立即转为拒绝终态，拒绝
351	// 信息说明策略被停用并包含停用理由，决定时间为停用时间；已到（含恰到）
352	// 或超过等待期限的待审批请求进入过期终态。两类处理都不冻结余额、不占用
353	// 额度，也不产生退款；其他状态的请求与其他策略不受影响。
354	func (w *Wallet) DeactivatePolicy(policyID, sessionID, deviceID, reason string) (PolicyView, error) {
355		reason = strings.TrimSpace(reason)
356		if policyID == "" || sessionID == "" || deviceID == "" || reason == "" {
357			return PolicyView{}, fmt.Errorf("%w: policy id, session id, device id and reason are required", ErrInvalidArgument)
358		}
359	
360		w.mu.Lock()
361		defer w.mu.Unlock()
362	
363		p, ok := w.policies[policyID]
364		if !ok {
365			return PolicyView{}, fmt.Errorf("%w: %s", ErrPolicyNotFound, policyID)
366		}
367		now := w.now()
368		if err := w.checkPolicyOwnerLocked(p, sessionID, deviceID, now); err != nil {
369			return PolicyView{}, err
370		}
371		// 鉴权通过后先释放已到期预留（停用不缩短任何未到期请求的截止时间）。
372		w.expireReservationsLocked(now)
373	
374		if p.deactivated {
375			// 停用不可撤销：理由相同返回首次结果，理由不同返回冲突，
376			// 均不改写首次信息、不增加账本记录。
377			if p.deactivateReason == reason {
378				return p.view(), nil
379			}
380			return PolicyView{}, fmt.Errorf("%w: policy %s was already deactivated with a different reason", ErrConflict, policyID)
381		}
382	
383		p.deactivated = true
384		p.deactivatedAt = now
385		p.deactivatorAccountID = p.payerAccountID
386		p.deactivateReason = reason
387	
388		w.ledger = append(w.ledger, LedgerEntry{
389			Kind:      LedgerPolicyDeactivation,
390			AccountID: p.payerAccountID,
391			PolicyID:  p.id,
392			Reason:    reason,
393			At:        now,
394		})
395	
396		// 停用瞬间结清该策略全部待审批请求：未到等待期限的随停用立即拒绝，
397		// 已到或超过期限的进入过期终态（不能因未被查询过而变成停用拒绝）。
398		pending := make([]*request, 0)
399		for _, req := range w.requests {
400			if req.policyID == p.id && req.state == RequestPendingApproval {
401				pending = append(pending, req)
402			}
403		}
404		w.settlePendingLocked(pending, now, func(req *request) {
405			msg := fmt.Sprintf("policy %s deactivated by payer: %s", p.id, reason)
406			req.state = RequestRejected
407			req.rejectReason = msg
408			req.decidedAt = now
409			req.approverAccountID = p.payerAccountID
410			w.ledger = append(w.ledger, LedgerEntry{
411				Kind:      LedgerRejection,
412				AccountID: req.accountID,
413				RequestID: req.requestID,
414				Reason:    msg,
415				At:        now,
416			})
417		})
418		return p.view(), nil
419	}
420	
421	// checkPolicyOwnerLocked 在持锁状态下校验停用会话：必须存在、归属策略的
422	// 出资账户、绑定当前设备、未吊销且未到期。任一不满足都返回
423	// ErrNotPolicyOwner，且不改变策略、请求或账本。
424	func (w *Wallet) checkPolicyOwnerLocked(p *policy, sessionID, deviceID string, now time.Time) error {
425		sess, ok := w.sessions[sessionID]
426		if !ok {
427			return fmt.Errorf("%w: session %s", ErrNotPolicyOwner, sessionID)
428		}
429		if sess.accountID != p.payerAccountID {
430			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotPolicyOwner, sess.id, sess.accountID, p.payerAccountID)
431		}
432		if sess.deviceID != deviceID {
433			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotPolicyOwner, sess.id, sess.deviceID, deviceID)
434		}
435		if sess.revoked {
436			return fmt.Errorf("%w: session %s revoked", ErrNotPolicyOwner, sess.id)
437		}
438		if !now.Before(sess.expiresAt) {
439			return fmt.Errorf("%w: session %s expired at %s", ErrNotPolicyOwner, sess.id, sess.expiresAt.Format(time.RFC3339))
440		}
441		return nil
442	}
443	
444	// Apply 提交一笔代付申请。
445	//
446	// 校验顺序为：申请字段 -> 使用账户 -> 会话（存在性、归属、设备、吊销、
447	// 到期）-> 幂等请求编号 -> 策略授权与额度 -> 出资账户余额。任一环节
448	// 失败都会在账本中留下带具体原因的拒绝记录，不产生任何扣款或预留。
449	//
450	// 同一使用账户以相同请求编号重复申请：策略、操作类型、收款方和预估
451	// 费用一致时直接返回已有请求（不再预留）；任一不同则返回 ErrConflict。
452	func (w *Wallet) Apply(in RequestInput) (RequestView, error) {
453		if in.EstimatedFee <= 0 {
454			return RequestView{}, w.reject(in, fmt.Errorf("%w: estimated fee must be positive", ErrInvalidAmount))
455		}
456		if in.AccountID == "" || in.SessionID == "" || in.DeviceID == "" || in.RequestID == "" || in.PolicyID == "" {
457			return RequestView{}, w.reject(in, fmt.Errorf("%w: account, session, device, policy and request id are required", ErrInvalidArgument))
458		}
459	
460		w.mu.Lock()
461		defer w.mu.Unlock()
462	
463		now := w.now()
464	
465		acc, ok := w.accounts[in.AccountID]
466		if !ok {
467			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrAccountNotFound, in.AccountID))
468		}
469		_ = acc
470	
471		sess, ok := w.sessions[in.SessionID]
472		if !ok {
473			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrSessionNotFound, in.SessionID))
474		}
475		if sess.accountID != in.AccountID {
476			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s belongs to account %s", ErrSessionAccountMismatch, sess.id, sess.accountID))
477		}
478		if sess.deviceID != in.DeviceID {
479			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s is bound to device %s", ErrSessionDeviceMismatch, sess.id, sess.deviceID))
480		}
481		if sess.revoked {
482			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s", ErrSessionRevoked, sess.id))
483		}
484		// 到期时刻及之后一律视为过期：[零值, ExpiresAt) 才有效。
485		if !now.Before(sess.expiresAt) {
486			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: session %s expired at %s", ErrSessionExpired, sess.id, sess.expiresAt.Format(time.RFC3339)))
487		}
488	
489		key := requestKey{accountID: in.AccountID, requestID: in.RequestID}
490		if existing, ok := w.requests[key]; ok {
491			// 待审批到期即过期、已预留到期即自动退回，重复申请看到的应是最新终态。
492			w.refreshPendingLocked(existing, now)
493			w.refreshReservedLocked(existing, now)
494			if existing.policyID == in.PolicyID &&
495				existing.operation == in.Operation &&
496				existing.payee == in.Payee &&
497				existing.estimatedFee == in.EstimatedFee {
498				// 幂等命中：直接返回已有结果，不再预留、不记账。
499				return existing.view(), nil
500			}
501			return RequestView{}, fmt.Errorf("%w: account %s request %s was already submitted with different content", ErrConflict, in.AccountID, in.RequestID)
502		}
503	
504		p, ok := w.policies[in.PolicyID]
505		if !ok {
506			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: %s", ErrPolicyNotFound, in.PolicyID))
507		}
508		// 停用后的策略不再受理新申请；历史请求的幂等查询在上方已先行处理。
509		if p.deactivated {
510			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: policy %s deactivated: %s", ErrPolicyDeactivated, p.id, p.deactivateReason))
511		}
512		if _, ok := p.allowedAccounts[in.AccountID]; !ok {
513			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: account %s is not allowed by policy %s", ErrPolicyDenied, in.AccountID, p.id))
514		}
515		if in.Operation != p.operation {
516			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: operation %q does not match policy %q", ErrPolicyDenied, in.Operation, p.operation))
517		}
518		if in.Payee != p.payee {
519			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payee %q does not match policy %q", ErrPolicyDenied, in.Payee, p.payee))
520		}
521		// 时间窗含开始、不含结束：[StartsAt, EndsAt)。
522		if now.Before(p.startsAt) || !now.Before(p.endsAt) {
523			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: current time %s is outside policy window [%s, %s)", ErrPolicyDenied,
524				now.Format(time.RFC3339), p.startsAt.Format(time.RFC3339), p.endsAt.Format(time.RFC3339)))
525		}
526		if in.EstimatedFee > p.maxPerRequest {
527			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d exceeds per-request limit %d", ErrQuotaExceeded, in.EstimatedFee, p.maxPerRequest))
528		}
529		// 资金与额度检查前释放所有已到期预留（含同一出资账户在其他策略下的
530		// 预留），因此先查余额还是先申请看到的可用金额都一致。
531		w.expireReservationsLocked(now)
532		// 预留中的费用同样占用共享累计额度。
533		if used, exceed := quotaWouldExceedLocked(p, in.EstimatedFee); exceed {
534			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
535				ErrQuotaExceeded, in.EstimatedFee, p.maxTotal, used))
536		}
537	
538		payer, ok := w.accounts[p.payerAccountID]
539		if !ok {
540			// 保存策略时已校验，这里仅作防御。
541			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("payer account %s: %w", p.payerAccountID, ErrAccountNotFound))
542		}
543		if payer.available < in.EstimatedFee {
544			return RequestView{}, w.rejectLocked(in, now, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, in.EstimatedFee))
545		}
546	
547		// 所有硬性检查通过：预估费用严格超过审批门槛的进入待审批，其余直接预留。
548		if p.approvalThreshold > 0 && in.EstimatedFee > p.approvalThreshold {
549			// 待审批不冻结余额、不占用共享累计额度。期限取提交时刻 + 等待时长、
550			// 策略结束时间、申请会话到期时间三者中的最早值。
551			deadline := now.Add(p.approvalWait)
552			if p.endsAt.Before(deadline) {
553				deadline = p.endsAt
554			}
555			if sess.expiresAt.Before(deadline) {
556				deadline = sess.expiresAt
557			}
558			req := &request{
559				policyID:       p.id,
560				requestID:      in.RequestID,
561				accountID:      in.AccountID,
562				payerAccountID: payer.id,
563				sessionID:      sess.id,
564				operation:      in.Operation,
565				payee:          in.Payee,
566				estimatedFee:   in.EstimatedFee,
567				state:          RequestPendingApproval,
568				createdAt:      now,
569				waitDeadline:   deadline,
570			}
571			w.requests[key] = req
572			w.ledger = append(w.ledger, LedgerEntry{
573				Kind:      LedgerPendingApproval,
574				AccountID: in.AccountID,
575				RequestID: in.RequestID,
576				Reason:    "pending approval for large amount",
577				At:        now,
578			})
579			return req.view(), nil
580		}
581	
582		// 受理：从出资账户可用余额中预留预估费用。
583		payer.available -= in.EstimatedFee
584		payer.reserved += in.EstimatedFee
585		p.reservedTotal += in.EstimatedFee
586	
587		req := &request{
588			policyID:       p.id,
589			requestID:      in.RequestID,
590			accountID:      in.AccountID,
591			payerAccountID: payer.id,
592			sessionID:      sess.id,
593			operation:      in.Operation,
594			payee:          in.Payee,
595			estimatedFee:   in.EstimatedFee,
596			state:          RequestReserved,
597			createdAt:      now,
598		}
599		// 直接受理：从受理时刻起算最长预留时长。
600		withReserveTimingLocked(req, p, now)
601		w.requests[key] = req
602		w.ledger = append(w.ledger, LedgerEntry{
603			Kind:      LedgerReserve,
604			AccountID: payer.id,
605			RequestID: in.RequestID,
606			Amount:    in.EstimatedFee,
607			Reason:    "reserve estimated fee",
608			At:        now,
609		})
610		return req.view(), nil
611	}
612	
613	// Settle 结算一笔已预留的代付请求。
614	//
615	// actualFee 允许为零但不得为负、不得超过预留的预估费用。结算时扣除
616	// 实际费用并把差额退回可用余额。以相同实际费用重复结算幂等返回，不
617	// 重复记账；不同实际费用返回 ErrConflict。已取消的请求不能结算。
618	func (w *Wallet) Settle(accountID, requestID string, actualFee int64) (RequestView, error) {
619		if actualFee < 0 {
620			return RequestView{}, fmt.Errorf("%w: actual fee must not be negative", ErrInvalidAmount)
621		}
622		w.mu.Lock()
623		defer w.mu.Unlock()
624	
625		req, p, err := w.lookupRequest(accountID, requestID)
626		if err != nil {
627			return RequestView{}, err
628		}
629		now := w.now()
630		w.refreshPendingLocked(req, now)
631		// 已到最长预留时长的预留先自动退回：此后任何结算都不能再扣款。
632		w.refreshReservedLocked(req, now)
633		switch req.state {
634		case RequestSettled:
635			if req.actualFee == actualFee {
636				return req.view(), nil
637			}
638			return RequestView{}, fmt.Errorf("%w: request %s already settled with actual fee %d", ErrConflict, requestID, req.actualFee)
639		case RequestCancelled:
640			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadyCancelled, requestID)
641		case RequestReservationExpired:
642			// 预留已超时全额退回：传入非负实际费用也返回明确的超时错误，不能扣款。
643			return RequestView{}, fmt.Errorf("%w: request %s reservation expired at %s", ErrReservationExpired, requestID, req.reserveExpiredAt.Format(time.RFC3339))
644		case RequestPendingApproval, RequestRejected, RequestExpired:
645			// 结算只允许处理已预留请求。
646			return RequestView{}, fmt.Errorf("%w: request %s is %v, only reserved requests can be settled", ErrRequestNotReserved, requestID, req.state)
647		}
648	
649		if actualFee > req.estimatedFee {
650			// 拒绝并保留预留。
651			return RequestView{}, fmt.Errorf("%w: actual %d > estimated %d for request %s", ErrSettleTooLarge, actualFee, req.estimatedFee, requestID)
652		}
653	
654		payer := w.accounts[req.payerAccountID]
655		refund := req.estimatedFee - actualFee
656	
657		// 扣除实际费用、退回差额、释放共享额度。
658		payer.reserved -= req.estimatedFee
659		payer.available += refund
660		p.reservedTotal -= req.estimatedFee
661		p.spentTotal += actualFee
662	
663		req.state = RequestSettled
664		req.actualFee = actualFee
665		req.settledAt = now
666	
667		w.ledger = append(w.ledger, LedgerEntry{
668			Kind:      LedgerSettle,
669			AccountID: payer.id,
670			RequestID: requestID,
671			Amount:    actualFee,
672			Reason:    "settle actual fee",
673			At:        now,
674		})
675		if refund > 0 {
676			w.ledger = append(w.ledger, LedgerEntry{
677				Kind:      LedgerRefund,
678				AccountID: payer.id,
679				RequestID: requestID,
680				Amount:    refund,
681				Reason:    "refund estimated-minus-actual fee",
682				At:        now,
683			})
684		}
685		return req.view(), nil
686	}
687	
688	// Cancel 取消一笔尚未结算的代付请求。
689	//
690	// 待审批请求取消后直接进入取消终态，不产生退款（本就没有冻结余额）；
691	// 已预留请求取消后全部预留退回。已结算的请求不能取消；重复取消幂等
692	// 返回，不重复记账。已拒绝或已过期的请求不能取消。
693	func (w *Wallet) Cancel(accountID, requestID string) (RequestView, error) {
694		w.mu.Lock()
695		defer w.mu.Unlock()
696	
697		req, p, err := w.lookupRequest(accountID, requestID)
698		if err != nil {
699			return RequestView{}, err
700		}
701		now := w.now()
702		w.refreshPendingLocked(req, now)
703		// 已到最长预留时长的预留先自动退回。
704		w.refreshReservedLocked(req, now)
705		switch req.state {
706		case RequestCancelled:
707			return req.view(), nil
708		case RequestSettled:
709			return RequestView{}, fmt.Errorf("%w: request %s", ErrAlreadySettled, requestID)
710		case RequestReservationExpired:
711			// 预留已超时自动全额退回：取消幂等返回已有超时结果，不重复退回、不留痕。
712			return req.view(), nil
713		case RequestPendingApproval:
714			// 待审批取消：无资金冻结，直接留取消终态。
715			req.state = RequestCancelled
716			req.decidedAt = now
717			w.ledger = append(w.ledger, LedgerEntry{
718				Kind:      LedgerCancellation,
719				AccountID: req.accountID,
720				RequestID: req.requestID,
721				Reason:    "cancel pending-approval request",
722				At:        now,
723			})
724			return req.view(), nil
725		case RequestRejected, RequestExpired:
726			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot cancel", ErrRequestNotReserved, requestID, req.state)
727		}
728	
729		// 已预留：退回全部预留。
730		payer := w.accounts[req.payerAccountID]
731	
732		payer.reserved -= req.estimatedFee
733		payer.available += req.estimatedFee
734		p.reservedTotal -= req.estimatedFee
735	
736		req.state = RequestCancelled
737	
738		w.ledger = append(w.ledger, LedgerEntry{
739			Kind:      LedgerRefund,
740			AccountID: payer.id,
741			RequestID: requestID,
742			Amount:    req.estimatedFee,
743			Reason:    "refund reserved fee on cancel",
744			At:        now,
745		})
746		return req.view(), nil
747	}
748	
749	// Approve 批准一笔待审批的大额代付请求。
750	//
751	// 审批必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
752	// 会话返回 ErrNotApprover 无权审批，且不改变请求。批准时再次检查出资
753	// 余额与共享剩余额度，足够才一次性预留全部预估费用并转为已预留；不足
754	// 时返回具体原因，保留待审批状态，期限内可再次批准。
755	//
756	// 已批准并处于预留或结算状态的请求重复批准只返回当前结果，不重复预留；
757	// 已拒绝、过期或取消的请求不能批准。截止时刻及之后不能批准。
758	func (w *Wallet) Approve(accountID, requestID, sessionID, deviceID string) (RequestView, error) {
759		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
760			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
761		}
762		w.mu.Lock()
763		defer w.mu.Unlock()
764	
765		now := w.now()
766		req, p, err := w.lookupRequest(accountID, requestID)
767		if err != nil {
768			return RequestView{}, err
769		}
770		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
771			return RequestView{}, err
772		}
773		// 鉴权通过后释放已到期预留（含同一出资账户在其他策略下的预留），使
774		// 批准的余额与额度检查计入退回；因余额或额度不足而失败的批准不会开始
775		// 预留计时。
776		w.expireReservationsLocked(now)
777		w.refreshPendingLocked(req, now)
778		if req.state == RequestExpired {
779			return RequestView{}, fmt.Errorf("%w: approval deadline %s passed", ErrApprovalExpired, req.waitDeadline.Format(time.RFC3339))
780		}
781	
782		switch req.state {
783		case RequestPendingApproval:
784			payer := w.accounts[req.payerAccountID]
785			if payer.available < req.estimatedFee {
786				return RequestView{}, fmt.Errorf("%w: payer %s available %d, need %d", ErrInsufficientBalance, payer.id, payer.available, req.estimatedFee)
787			}
788			if used, exceed := quotaWouldExceedLocked(p, req.estimatedFee); exceed {
789				return RequestView{}, fmt.Errorf("%w: estimated fee %d would exceed shared total limit %d (used %d)",
790					ErrQuotaExceeded, req.estimatedFee, p.maxTotal, used)
791			}
792			// 一次性预留全部预估费用。
793			payer.available -= req.estimatedFee
794			payer.reserved += req.estimatedFee
795			p.reservedTotal += req.estimatedFee
796	
797			req.state = RequestReserved
798			req.decidedAt = now
799			req.approverAccountID = payer.id
800			// 待审批请求：等待审批的时间不计入，从批准成功时刻起算最长预留时长。
801			withReserveTimingLocked(req, p, now)
802	
803			w.ledger = append(w.ledger,
804				LedgerEntry{
805					Kind:      LedgerReserve,
806					AccountID: payer.id,
807					RequestID: req.requestID,
808					Amount:    req.estimatedFee,
809					Reason:    "reserve estimated fee on approval",
810					At:        now,
811				},
812				LedgerEntry{
813					Kind:      LedgerApproval,
814					AccountID: req.accountID,
815					RequestID: req.requestID,
816					Reason:    "approve large-amount request",
817					At:        now,
818				},
819			)
820			return req.view(), nil
821		case RequestReserved, RequestSettled:
822			// 已批准：重复批准幂等返回，不重复预留。
823			return req.view(), nil
824		default:
825			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot approve", ErrRequestNotPending, requestID, req.state)
826		}
827	}
828	
829	// Reject 拒绝一笔待审批的大额代付请求。
830	//
831	// 拒绝必须使用该策略出资账户绑定当前设备的有效会话；其他账户或无效
832	// 会话返回 ErrNotApprover 无权审批，且不改变请求。拒绝理由为空或全为
833	// 空白时返回 ErrInvalidArgument 参数错误，请求保持不变。
834	//
835	// 重复拒绝且理由一致时幂等返回，不重复留痕；理由不同返回 ErrConflict。
836	// 已批准（含预留、结算）、已过期或已取消的请求不能拒绝。
837	func (w *Wallet) Reject(accountID, requestID, sessionID, deviceID, reason string) (RequestView, error) {
838		if strings.TrimSpace(reason) == "" {
839			return RequestView{}, fmt.Errorf("%w: reject reason must not be empty or blank", ErrInvalidArgument)
840		}
841		if accountID == "" || requestID == "" || sessionID == "" || deviceID == "" {
842			return RequestView{}, fmt.Errorf("%w: account, request, session and device ids are required", ErrInvalidArgument)
843		}
844		w.mu.Lock()
845		defer w.mu.Unlock()
846	
847		now := w.now()
848		req, _, err := w.lookupRequest(accountID, requestID)
849		if err != nil {
850			return RequestView{}, err
851		}
852		if err := w.checkApproverLocked(req, sessionID, deviceID, now); err != nil {
853			return RequestView{}, err
854		}
855		w.refreshPendingLocked(req, now)
856	
857		switch req.state {
858		case RequestPendingApproval:
859			req.state = RequestRejected
860			req.rejectReason = reason
861			req.decidedAt = now
862			req.approverAccountID = req.payerAccountID
863	
864			w.ledger = append(w.ledger, LedgerEntry{
865				Kind:      LedgerRejection,
866				AccountID: req.accountID,
867				RequestID: req.requestID,
868				Reason:    reason,
869				At:        now,
870			})
871			return req.view(), nil
872		case RequestRejected:
873			if req.rejectReason == reason {
874				return req.view(), nil
875			}
876			return RequestView{}, fmt.Errorf("%w: request %s already rejected with a different reason", ErrConflict, requestID)
877		default:
878			return RequestView{}, fmt.Errorf("%w: request %s is %v, cannot reject", ErrRequestNotPending, requestID, req.state)
879		}
880	}
881	
882	// checkApproverLocked 在持锁状态下校验审批会话：必须存在、归属出资账户、
883	// 绑定当前设备、未吊销且未过期。任一不满足都返回 ErrNotApprover，且不
884	// 改变请求。
885	func (w *Wallet) checkApproverLocked(req *request, sessionID, deviceID string, now time.Time) error {
886		sess, ok := w.sessions[sessionID]
887		if !ok {
888			return fmt.Errorf("%w: session %s", ErrNotApprover, sessionID)
889		}
890		if sess.accountID != req.payerAccountID {
891			return fmt.Errorf("%w: session %s belongs to account %s, not payer %s", ErrNotApprover, sess.id, sess.accountID, req.payerAccountID)
892		}
893		if sess.deviceID != deviceID {
894			return fmt.Errorf("%w: session %s is bound to device %s, not %s", ErrNotApprover, sess.id, sess.deviceID, deviceID)
895		}
896		if sess.revoked {
897			return fmt.Errorf("%w: session %s revoked", ErrNotApprover, sess.id)
898		}
899		if !now.Before(sess.expiresAt) {
900			return fmt.Errorf("%w: session %s expired at %s", ErrNotApprover, sess.id, sess.expiresAt.Format(time.RFC3339))
901		}
902		return nil
903	}
904	
905	// refreshPendingLocked 在持锁状态下检查待审批请求是否已到期限；到期
906	// （含到期时刻）则转为过期终态并记账。必须在持锁状态下调用。
907	func (w *Wallet) refreshPendingLocked(req *request, now time.Time) {
908		if req.state != RequestPendingApproval {
909			return
910		}
911		if now.Before(req.waitDeadline) {
912			return
913		}
914		w.expirePendingLocked(req, now)
915	}
916	
917	// expirePendingLocked 将一笔待审批请求转为过期终态：决定时间记录本次处理
918	// 时刻，拒绝理由与审批账户保持为空，账本只追加一条关联使用账户与请求编号
919	// 的零金额过期记录。不冻结或退回费用，不改变任何余额与额度。必须在持锁
920	// 状态下调用。
921	func (w *Wallet) expirePendingLocked(req *request, now time.Time) {
922		req.state = RequestExpired
923		req.decidedAt = now
924		w.ledger = append(w.ledger, LedgerEntry{
925			Kind:      LedgerExpiration,
926			AccountID: req.accountID,
927			RequestID: req.requestID,
928			Reason:    "approval period expired",
929			At:        now,
930		})
931	}
932	
933	// settlePendingLocked 按等待截止时刻顺序（同截止时刻按使用账户、请求编号
934	// 排序）分别结清 reqs 中仍在待审批的请求，保证账本追加顺序确定。每笔请求
935	// 只按自己的等待截止时间判断：now 严格早于截止时间且 reject 非空时调用
936	// reject 进入拒绝终态（拒绝理由与审批账户由调用方决定），恰到或超过截止
937	// 时间的进入过期终态；已到期的与仍在等待的请求互不影响，不因共用会话或
938	// 策略而混同。两类处理都不冻结费用、不改变余额与额度。必须在持锁状态下
939	// 调用。
940	func (w *Wallet) settlePendingLocked(reqs []*request, now time.Time, reject func(req *request)) {
941		sortRequestsByDeadline(reqs, func(req *request) time.Time { return req.waitDeadline })
942		for _, req := range reqs {
943			if req.state != RequestPendingApproval {
944				continue
945			}
946			if now.Before(req.waitDeadline) {
947				if reject != nil {
948					reject(req)
949				}
950				continue
951			}
952			w.expirePendingLocked(req, now)
953		}
954	}
955	
956	// sortRequestsByDeadline 按 deadline 给出的截止时刻排序（同截止时刻按使用
957	// 账户、请求编号排序），供各类批量到期处理共用，保证账本追加顺序确定。
958	func sortRequestsByDeadline(reqs []*request, deadline func(req *request) time.Time) {
959		sort.SliceStable(reqs, func(i, j int) bool {
960			if di, dj := deadline(reqs[i]), deadline(reqs[j]); !di.Equal(dj) {
961				return di.Before(dj)
962			}
963			if reqs[i].accountID != reqs[j].accountID {
964				return reqs[i].accountID < reqs[j].accountID
965			}
966			return reqs[i].requestID < reqs[j].requestID
967		})
968	}
969	
970	// refreshReservedLocked 在持锁状态下检查单笔已预留请求是否已到最长预留
971	// 时长；截止时刻及之后转为“预留超时”终态并退回全额预留。必须在持锁状态
972	// 下调用。
973	func (w *Wallet) refreshReservedLocked(req *request, now time.Time) {
974		if req.state != RequestReserved || req.reserveDuration <= 0 {
975			return
976		}
977		if now.Before(req.reserveDeadline) {
978			return
979		}
980		w.expireReservationLocked(req, req.reserveDeadline)
981	}
982	
983	// expirePendingApprovalsLocked 惰性结清当前全部已到等待期限（含到期时刻）
984	// 的待审批请求，使它们进入过期终态并留下状态记录。必须在持锁状态下调用。
985	func (w *Wallet) expirePendingApprovalsLocked(now time.Time) {
986		pending := make([]*request, 0)
987		for _, req := range w.requests {
988			if req.state == RequestPendingApproval {
989				pending = append(pending, req)
990			}
991		}
992		w.settlePendingLocked(pending, now, nil)
993	}
994	
995	// expireReservationsLocked 惰性结清当前全部已到期（含到期时刻）的预留。
996	// 所有账户/余额/策略/请求/账本查询以及新申请、批准的资金检查入口都先调用
997	// 它，因此调用者无须逐笔取消即可看到已到期预留的释放结果。释放时间一律
998	// 记录为各请求自己的截止时刻，而不是处理时刻；账本按截止时刻顺序追加。
999	// 必须在持锁状态下调用。
1000	func (w *Wallet) expireReservationsLocked(now time.Time) {
1001		due := make([]*request, 0)
1002		for _, req := range w.requests {
1003			if req.state == RequestReserved && req.reserveDuration > 0 && !now.Before(req.reserveDeadline) {
1004				due = append(due, req)
1005			}
1006		}
1007		sortRequestsByDeadline(due, func(req *request) time.Time { return req.reserveDeadline })
1008		for _, req := range due {
1009			w.expireReservationLocked(req, req.reserveDeadline)
1010		}
1011	}
1012	
1013	// expireReservationLocked 将一笔已预留请求转为 RequestReservationExpired
1014	// 终态：全额退回预估费用到出资账户可用余额，减少出资账户预留余额与该
1015	// 策略的预留总额，不增加实际费用或已花费总额。账本增加一条出资账户的
1016	// 全额退款记录和一条使用账户的零金额超时状态记录，均关联请求编号。
1017	// 必须在持锁状态下调用。
1018	func (w *Wallet) expireReservationLocked(req *request, deadline time.Time) {
1019		payer := w.accounts[req.payerAccountID]
1020		payer.reserved -= req.estimatedFee
1021		payer.available += req.estimatedFee
1022		if p := w.policies[req.policyID]; p != nil {
1023			p.reservedTotal -= req.estimatedFee
1024		}
1025		req.state = RequestReservationExpired
1026		req.reserveExpiredAt = deadline
1027	
1028		w.ledger = append(w.ledger,
1029			LedgerEntry{
1030				Kind:      LedgerRefund,
1031				AccountID: payer.id,
1032				RequestID: req.requestID,
1033				Amount:    req.estimatedFee,
1034				Reason:    "refund reserved fee on reservation timeout",
1035				At:        deadline,
1036			},
1037			LedgerEntry{
1038				Kind:      LedgerReservationExpiration,
1039				AccountID: req.accountID,
1040				RequestID: req.requestID,
1041				Reason:    "reservation timed out before settlement",
1042				At:        deadline,
1043			},
1044		)
1045	}
1046	
1047	// withReserveTimingLocked 在费用完成预留时写入预留计时信息：预留时刻为
1048	// 受理/批准成功的时刻，截止时刻为预留时刻加策略最长预留时长；策略未启用
1049	// 超时（时长为零）时截止时刻保持零值。必须在持锁状态下调用。
1050	func withReserveTimingLocked(req *request, p *policy, reservedAt time.Time) {
1051		req.reservedAt = reservedAt
1052		req.reserveDuration = p.maxReserveDuration
1053		if p.maxReserveDuration > 0 {
1054			req.reserveDeadline = reservedAt.Add(p.maxReserveDuration)
1055		}
1056	}
1057	
1058	// quotaWouldExceedLocked 判断在策略 p 上再计入 fee 后，共享累计合计是否
1059	// 严格超过累计上限，并返回计入前“现存预留 + 已结算实际费用”的合计（用于
1060	// 错误信息；该合计本身越过 int64 范围时返回 0）。现存预留、已结算实际费用
1061	// 与本次费用各自合法、但合计越过 int64 范围时 exceed 同样为 true：不能让
1062	// 求和回绕成小（或负）数后被当成额度充足。累计上限与单次上限仍允许取
1063	// int64 最大值，这里不缩小金额范围。必须在持锁状态下调用。
1064	func quotaWouldExceedLocked(p *policy, fee int64) (used int64, exceed bool) {
1065		used, ok := addInt64(p.reservedTotal, p.spentTotal)
1066		if !ok {
1067			return 0, true
1068		}
1069		total, ok := addInt64(used, fee)
1070		if !ok {
1071			return used, true
1072		}
1073		return used, total > p.maxTotal
1074	}
1075	
1076	// Request 查询某使用账户下的代付请求。待审批请求到期即转为过期终态，
1077	// 已预留请求到最长预留时长即转为预留超时终态，查询结果反映最新状态；
1078	// 超时释放时间记录的是截止时刻本身，而不是本次查询时刻。
1079	func (w *Wallet) Request(accountID, requestID string) (RequestView, error) {
1080		w.mu.Lock()
1081		defer w.mu.Unlock()
1082	
1083		req, _, err := w.lookupRequest(accountID, requestID)
1084		if err != nil {
1085			return RequestView{}, err
1086		}
1087		now := w.now()
1088		w.refreshPendingLocked(req, now)
1089		w.refreshReservedLocked(req, now)
1090		return req.view(), nil
1091	}
1092	
1093	// Ledger 返回全部账本记录的副本，按产生顺序排列。
1094	// 申请被拒绝的记录（Kind 为 LedgerRejection）也包含在内并带有原因。
1095	// 查询时已到期预留的自动退款与超时留痕也会在返回前补齐。
1096	func (w *Wallet) Ledger() []LedgerEntry {
1097		w.mu.Lock()
1098		defer w.mu.Unlock()
1099	
1100		w.expireReservationsLocked(w.now())
1101		out := make([]LedgerEntry, len(w.ledger))
1102		copy(out, w.ledger)
1103		return out
1104	}
1105	
1106	// AccountLedger 返回与指定账户相关的账本记录副本。
1107	//
1108	// 对出资账户返回预留、扣减、退回等资金变动记录；对待审批、批准、拒绝、
1109	// 取消、过期等状态记录（无金额变动），其 AccountID 为发起申请的使用
1110	// 账户，因此按使用账户查询可看到该请求的完整状态留痕。
1111	func (w *Wallet) AccountLedger(accountID string) []LedgerEntry {
1112		w.mu.Lock()
1113		defer w.mu.Unlock()
1114	
1115		w.expireReservationsLocked(w.now())
1116		var out []LedgerEntry
1117		for _, e := range w.ledger {
1118			if e.AccountID == accountID {
1119				out = append(out, e)
1120			}
1121		}
1122		return out
1123	}
1124	
1125	// lookupRequest 必须在持锁状态下调用。
1126	func (w *Wallet) lookupRequest(accountID, requestID string) (*request, *policy, error) {
1127		req, ok := w.requests[requestKey{accountID: accountID, requestID: requestID}]
1128		if !ok {
1129			return nil, nil, fmt.Errorf("%w: account %s request %s", ErrRequestNotFound, accountID, requestID)
1130		}
1131		return req, w.policies[req.policyID], nil
1132	}
1133	
1134	// reject 记录无需持锁快速校验阶段的拒绝（当前没有此类调用，保留对称接口）。
1135	func (w *Wallet) reject(in RequestInput, cause error) error {
1136		w.mu.Lock()
1137		defer w.mu.Unlock()
1138		w.appendRejection(in, w.now(), cause)
1139		return cause
1140	}
1141	
1142	// rejectLocked 在持锁状态下记录拒绝原因并原样返回错误。
1143	func (w *Wallet) rejectLocked(in RequestInput, at time.Time, cause error) error {
1144		w.appendRejection(in, at, cause)
1145		return cause
1146	}
1147	
1148	// appendRejection 必须在持锁状态下调用。拒绝记录不涉及金额变动，
1149	// 只记录使用账户、请求编号与具体原因。
1150	func (w *Wallet) appendRejection(in RequestInput, at time.Time, cause error) {
1151		w.ledger = append(w.ledger, LedgerEntry{
1152			Kind:      LedgerRejection,
1153			AccountID: in.AccountID,
1154			RequestID: in.RequestID,
1155			Reason:    cause.Error(),
1156			At:        at,
1157		})
1158	}
1159	
1160	func (a *account) view() AccountView {
1161		return AccountView{
1162			ID: a.id,
1163			Balances: Balances{
1164				Available: a.available,
1165				Reserved:  a.reserved,
1166			},
1167			CreatedAt: a.createdAt,
1168		}
1169	}
1170	
1171	func (s *session) view() SessionView {
1172		state := SessionActive
1173		if s.revoked {
1174			state = SessionRevoked
1175		}
1176		return SessionView{
1177			ID:        s.id,
1178			AccountID: s.accountID,
1179			DeviceID:  s.deviceID,
1180			ExpiresAt: s.expiresAt,
1181			State:     state,
1182			CreatedAt: s.createdAt,
1183		}
1184	}
1185	
1186	func (p *policy) view() PolicyView {
1187		ids := make([]string, 0, len(p.allowedAccounts))
1188		for id := range p.allowedAccounts {
1189			ids = append(ids, id)
1190		}
1191		return PolicyView{
1192			PolicySpec: PolicySpec{
1193				ID:                 p.id,
1194				PayerAccountID:     p.payerAccountID,
1195				AllowedAccountIDs:  ids,
1196				Operation:          p.operation,
1197				Payee:              p.payee,
1198				StartsAt:           p.startsAt,
1199				EndsAt:             p.endsAt,
1200				MaxPerRequest:      p.maxPerRequest,
1201				MaxTotal:           p.maxTotal,
1202				ApprovalThreshold:  p.approvalThreshold,
1203				ApprovalWait:       p.approvalWait,
1204				MaxReserveDuration: p.maxReserveDuration,
1205			},
1206			ReservedTotal:        p.reservedTotal,
1207			SpentTotal:           p.spentTotal,
1208			Deactivated:          p.deactivated,
1209			DeactivatedAt:        p.deactivatedAt,
1210			DeactivatorAccountID: p.deactivatorAccountID,
1211			DeactivateReason:     p.deactivateReason,
1212		}
1213	}
1214	
1215	func (r *request) view() RequestView {
1216		return RequestView{
1217			PolicyID:          r.policyID,
1218			RequestID:         r.requestID,
1219			AccountID:         r.accountID,
1220			PayerAccountID:    r.payerAccountID,
1221			Operation:         r.operation,
1222			Payee:             r.payee,
1223			EstimatedFee:      r.estimatedFee,
1224			ActualFee:         r.actualFee,
1225			State:             r.state,
1226			CreatedAt:         r.createdAt,
1227			SettledAt:         r.settledAt,
1228			WaitDeadline:      r.waitDeadline,
1229			ReservedAt:        r.reservedAt,
1230			ReserveDuration:   r.reserveDuration,
1231			ReserveDeadline:   r.reserveDeadline,
1232			ReserveExpiredAt:  r.reserveExpiredAt,
1233			DecidedAt:         r.decidedAt,
1234			ApproverAccountID: r.approverAccountID,
1235			RejectReason:      r.rejectReason,
1236		}
1237	}
