201	//   - 策略 p-big 单次/累计上限均为 MaxInt64，门槛 1、等待 1 小时，
202	//     最长预留时长 reserveDur（零表示关闭预留超时）；
203	//   - u1 一笔已结算实际费用 1（已花费 1，直接受理路径）；
204	//   - u2 一笔现存预留 big，预估 MaxInt64-2（批准路径，带批准信息），
205	//     预留时刻 t0、截止 t0+reserveDur；
206	//   - u1 一笔待审批 small，预估费用 2，提交于 t0，等待截止 t0+1h；
207	//   - 出资账户 payer 可用余额 2、预留余额 MaxInt64-2（可用+预留恰为
208	//     MaxInt64，备份自洽），现存预留与已花费合计 MaxInt64-1：再计入
209	//     small 的 2 会越过 int64 上限；
210	//   - 另有出资账户会话 sa（设备 dev-approve）供批准使用。
211	func buildApproveOverflowBackup(t *testing.T, t0 time.Time, reserveDur time.Duration) []byte {
212		t.Helper()
213		const (
214			spentActual = 1
215			bigFee      = math.MaxInt64 - 2
216			smallFee    = 2
217		)
218		settled := requestBackupV1{
219			PolicyID: "p-big", RequestID: "settled", AccountID: "u1", PayerAccountID: "payer",
220			SessionID: "s1", Operation: "charge", Payee: "shop",
221			EstimatedFee: spentActual, ActualFee: spentActual,
222			State:      int(RequestSettled),
223			CreatedAt:  timeJSON(t0.Add(-2 * time.Hour)),
224			ReservedAt: timeJSON(t0.Add(-2 * time.Hour)),
225			// 恰在预留完成时结算：无论是否启用预留超时都落在有效预留期起点，合法。
226			SettledAt: timeJSON(t0.Add(-2 * time.Hour)),
227		}
228		big := requestBackupV1{
229			PolicyID: "p-big", RequestID: "big", AccountID: "u2", PayerAccountID: "payer",
230			SessionID: "s2", Operation: "charge", Payee: "shop",
231			EstimatedFee:      bigFee,
232			State:             int(RequestReserved),
233			CreatedAt:         timeJSON(t0),
234			WaitDeadline:      timeJSON(t0.Add(time.Hour)),
235			ReservedAt:        timeJSON(t0),
236			ReserveDuration:   durationJSON(reserveDur),
237			ApproverAccountID: "payer",
238			DecidedAt:         timeJSON(t0),
239		}
240		if reserveDur > 0 {
241			big.ReserveDeadline = timeJSON(t0.Add(reserveDur))
242		}
243		small := requestBackupV1{
244			PolicyID: "p-big", RequestID: "small", AccountID: "u1", PayerAccountID: "payer",
245			SessionID: "s1", Operation: "charge", Payee: "shop",
246			EstimatedFee: smallFee,
247			State:        int(RequestPendingApproval),
248			CreatedAt:    timeJSON(t0),
249			WaitDeadline: timeJSON(t0.Add(time.Hour)),
250		}
251		// 已结算请求的预留时长快照必须与策略一致（备份自洽要求）。
252		settled.ReserveDuration = durationJSON(reserveDur)
253		if reserveDur > 0 {
254			settled.ReserveDeadline = timeJSON(t0.Add(-2 * time.Hour).Add(reserveDur))
255		}
256		b := backupV1{
257			Version:    backupVersion,
258			ExportedAt: timeJSON(t0),
259			Accounts: []accountBackupV1{
260				{ID: "payer", Available: 2, Reserved: bigFee, CreatedAt: timeJSON(t0)},
261				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
262				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
263			},
264			Sessions: []sessionBackupV1{
265				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
266				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
267				{ID: "sa", AccountID: "payer", DeviceID: "dev-approve", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
268			},
269			Policies: []policyBackupV1{{
270				ID: "p-big", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
271				Operation: "charge", Payee: "shop",
272				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
273				MaxPerRequest:      math.MaxInt64,
274				MaxTotal:           math.MaxInt64,
275				ApprovalThreshold:  1,
276				ApprovalWait:       durationJSON(time.Hour),
277				MaxReserveDuration: durationJSON(reserveDur),
278				ReservedTotal:      bigFee,
279				SpentTotal:         spentActual,
280			}},
281			Requests: []requestBackupV1{settled, big, small},
282			Ledger:   []ledgerEntryBackupV1{},
283		}
284		data, err := json.Marshal(&b)
285		if err != nil {
286			t.Fatal(err)
287		}
288		return data
289	}
290	
291	// approveSmall 以出资账户会话 sa 批准 u1 的待审批请求 small。
292	func approveSmall(w *Wallet) (RequestView, error) {
293		return w.Approve("u1", "small", "sa", "dev-approve")
294	}
295	
296	// TestApproveSharedQuotaOverflowKeepsPending 验证待审批请求批准前重新执行
297	// 溢出安全的累计额度判断：其他请求已占用额度使本次批准越过 int64 上限时，
298	// 批准返回 ErrQuotaExceeded，请求继续待审批，提交时间、等待截止时间与决定
299	// 信息不变，不开始预留计时、不新增预留或批准记录；取消释放额度后期限内仍
300	// 可再次批准。
301	func TestApproveSharedQuotaOverflowKeepsPending(t *testing.T) {
302		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
303		data := buildApproveOverflowBackup(t, t0, 0)
304		w, err := restoreAt(data, t0)
305		if err != nil {
306			t.Fatalf("restore: %v", err)
307		}
308		before, err := w.Request("u1", "small")
309		if err != nil {
310			t.Fatal(err)
311		}
312		if before.State != RequestPendingApproval {
313			t.Fatalf("setup state = %v, want pending", before.State)
314		}
315		// 余额恰好够（2），但额度合计 MaxInt64-1 再加 2 越过 int64 上限。
316		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
317			t.Fatalf("setup balance = %+v", bal)
318		}
319	
320		ledgerBefore := len(w.Ledger())
321		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
322			t.Fatalf("approve err = %v, want ErrQuotaExceeded", err)
323		}
324	
325		// 请求继续待审批，提交时间、等待截止时间与已有决定信息保持不变。
326		req, _ := w.Request("u1", "small")
327		if req.State != RequestPendingApproval {
328			t.Fatalf("state = %v, want still pending approval", req.State)
329		}
330		if !req.CreatedAt.Equal(before.CreatedAt) || !req.WaitDeadline.Equal(before.WaitDeadline) {
331			t.Fatalf("timing changed: created %v->%v deadline %v->%v",
332				before.CreatedAt, req.CreatedAt, before.WaitDeadline, req.WaitDeadline)
333		}
334		if !req.DecidedAt.Equal(time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
335			t.Fatalf("decision fields changed on failed approve: %+v", req)
336		}
337		// 不开始预留计时。
338		if !req.ReservedAt.Equal(time.Time{}) || req.ReserveDuration != 0 || !req.ReserveDeadline.Equal(time.Time{}) {
339			t.Fatalf("reserve timing started on failed approve: %+v", req)
340		}
341		// 不新增预留或批准记录，余额与额度不变。
342		if got := len(w.Ledger()); got != ledgerBefore {
343			t.Fatalf("ledger grew by %d on failed approve", got-ledgerBefore)
344		}
345		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
346			t.Fatalf("balance changed after failed approve: %+v", bal)
347		}
348		pv, _ := w.Policy("p-big")
349		if pv.ReservedTotal != math.MaxInt64-2 || pv.SpentTotal != 1 {
350			t.Fatalf("policy totals changed after failed approve: %+v", pv)
351		}
352	
353		// 期限内额度未释放时再次批准仍被拒绝。
354		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
355			t.Fatalf("second approve err = %v, want ErrQuotaExceeded", err)
356		}
357	
358		// 取消 u2 的大额预留，释放 MaxInt64-2 共享额度并全额退回余额。
359		if _, err := w.Cancel("u2", "big"); err != nil {
360			t.Fatal(err)
361		}
362		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
363			t.Fatalf("balance after cancel big = %+v", bal)
364		}
365		// 仍在等待期限内（时钟停在 t0，截止 t0+1h），释放后批准成功并预留 2。
366		req, err = approveSmall(w)
367		if err != nil {
368			t.Fatalf("approve after quota freed: %v", err)
369		}
370		if req.State != RequestReserved {
371			t.Fatalf("state = %v, want reserved", req.State)
372		}
373		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
374			t.Fatalf("balance after approve small = %+v", bal)
375		}
376		pv, _ = w.Policy("p-big")
377		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
378			t.Fatalf("policy totals after approve small = %+v", pv)
379		}
380	}
381	
382	// TestApproveOverflowReleasedByReservationTimeout 验证批准前的额度检查会计入
383	// 按现有规则已经到期的预留释放：大额预留超时自动全额退回、释放额度后，期限
384	// 内的待审批请求可以成功批准；释放之前仍按超额度拒绝。
385	func TestApproveOverflowReleasedByReservationTimeout(t *testing.T) {
386		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
387		data := buildApproveOverflowBackup(t, t0, time.Minute)
388	
389		// 恢复于 t0：大额预留截止 t0+1m 尚未到期，批准 small 仍超额度。
390		w, err := restoreAt(data, t0)
391		if err != nil {
392			t.Fatalf("restore at t0: %v", err)
393		}
394		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
395			t.Fatalf("approve before timeout release err = %v, want ErrQuotaExceeded", err)
396		}
397		if r, _ := w.Request("u1", "small"); r.State != RequestPendingApproval {
398			t.Fatalf("small state = %v, want still pending", r.State)
399		}
400	
401		// 恢复于 t0+2m：大额预留已过截止时刻，恢复时自动全额退回并释放额度；
402		// small 的等待截止 t0+1h 尚未到，仍可批准。
403		w2, err := restoreAt(data, t0.Add(2*time.Minute))
404		if err != nil {
405			t.Fatalf("restore after deadline: %v", err)
406		}
407		if r, _ := w2.Request("u2", "big"); r.State != RequestReservationExpired {
408			t.Fatalf("big state = %v, want reservation expired", r.State)
409		}
410		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
411			t.Fatalf("balance after timeout = %+v, want full refund", bal)
412		}
413		req, err := approveSmall(w2)
414		if err != nil {
415			t.Fatalf("approve after timeout release: %v", err)
416		}
417		if req.State != RequestReserved {
418			t.Fatalf("state = %v, want reserved", req.State)
419		}
420		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
421			t.Fatalf("balance after approve small = %+v", bal)
422		}
423		pv, _ := w2.Policy("p-big")
424		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
425			t.Fatalf("policy totals = %+v", pv)
426		}
427	}
428	
429	// TestApplyExactMaxInt64FillsQuota 验证单笔费用与上限均为 int64 最大值时
430	// 仍可正常受理（不缩小金额范围），占满后任何新费用都按超额度拒绝。
431	func TestApplyExactMaxInt64FillsQuota(t *testing.T) {
432		w, c := newTestWallet()
433		mustAccount(t, w, "payer", math.MaxInt64)
434		mustAccount(t, w, "u1", 0)
435		if _, err := w.CreateSession("s1", "u1", "d1", c.t.Add(time.Hour)); err != nil {
436			t.Fatal(err)
437		}
438		// 关闭审批：费用 MaxInt64 直接预留。
439		if err := w.SavePolicy(PolicySpec{
440			ID:                "p-direct",
441			PayerAccountID:    "payer",
442			AllowedAccountIDs: []string{"u1"},
443			Operation:         "charge",
444			Payee:             "shop",
445			StartsAt:          c.t.Add(-time.Hour),
446			EndsAt:            c.t.Add(24 * time.Hour),
447			MaxPerRequest:     math.MaxInt64,
448			MaxTotal:          math.MaxInt64,
449		}); err != nil {
450			t.Fatal(err)
451		}
452		in := RequestInput{
453			PolicyID: "p-direct", RequestID: "full", AccountID: "u1",
454			SessionID: "s1", DeviceID: "d1", Operation: "charge", Payee: "shop",
455			EstimatedFee: math.MaxInt64,
456		}
457		req, err := w.Apply(in)
458		if err != nil {
459			t.Fatalf("apply MaxInt64 fee: %v", err)
460		}
461		if req.State != RequestReserved {
462			t.Fatalf("state = %v, want reserved", req.State)
463		}
464		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 0, Reserved: math.MaxInt64}) {
465			t.Fatalf("balance = %+v, want {0 MaxInt64}", bal)
466		}
467		// 额度已占满：再申请费用 1 必须超额度拒绝（used+1 越过 int64 上限；
468		// 余额虽同样不足，但额度判断在前，仍返回 ErrQuotaExceeded）。
469		in.RequestID = "one-more"
470		in.EstimatedFee = 1
471		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
472			t.Fatalf("apply after quota full err = %v, want ErrQuotaExceeded", err)
473		}
474	}
